-- Tiger server schema, v1.
-- Requires PostgreSQL 16+ in a UTF-8 database, pgvector >= 0.8 (filtered HNSW needs iterative scan)
-- and pg_trgm (keyword leg; works for Japanese when the database locale is not plain "C").
-- IDs are UUIDv7 generated by the application.

CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE users (
  id          uuid PRIMARY KEY,
  email       text NOT NULL,
  name        text NOT NULL,
  avatar_url  text,
  locale      text NOT NULL DEFAULT 'ja' CHECK (locale IN ('ja', 'en')),
  google_sub  text UNIQUE,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_email_key ON users (lower(email));

-- Only the SHA-256 of a session token is stored.
CREATE TABLE sessions (
  token_hash    bytea PRIMARY KEY,
  user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at    timestamptz NOT NULL DEFAULT now(),
  last_seen_at  timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

CREATE TABLE spaces (
  id            uuid PRIMARY KEY,
  name          text NOT NULL,
  hue           text NOT NULL DEFAULT 'amber',
  created_by    uuid NOT NULL REFERENCES users (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  -- Tokens (input + output) the Space may spend per calendar month; NULL = unlimited.
  token_budget  bigint
);

CREATE TABLE space_members (
  space_id   uuid NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role       text NOT NULL CHECK (role IN ('owner', 'member')),
  joined_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (space_id, user_id)
);
CREATE INDEX space_members_user_idx ON space_members (user_id);

-- Only the SHA-256 of an invite token is stored; the token itself is shown once.
CREATE TABLE invites (
  id           uuid PRIMARY KEY,
  space_id     uuid NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  token_hash   bytea NOT NULL UNIQUE,
  email        text,
  created_by   uuid NOT NULL REFERENCES users (id),
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL,
  accepted_at  timestamptz,
  accepted_by  uuid REFERENCES users (id),
  revoked_at   timestamptz
);
CREATE INDEX invites_space_idx ON invites (space_id);

-- A shared item is one page in one Space. url_key is canonicalUrl(url) from @tiger/shared.
CREATE TABLE items (
  id                  uuid PRIMARY KEY,
  space_id            uuid NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  url                 text NOT NULL,
  url_key             text NOT NULL,
  title               text NOT NULL,
  source_type         text NOT NULL,
  shared_by           uuid NOT NULL REFERENCES users (id),
  shared_at           timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  status              text NOT NULL DEFAULT 'indexing' CHECK (status IN ('indexing', 'ready', 'failed')),
  current_version_id  uuid,
  UNIQUE (space_id, url_key)
);
CREATE INDEX items_url_key_idx ON items (url_key);

CREATE TABLE item_versions (
  id            uuid PRIMARY KEY,
  item_id       uuid NOT NULL REFERENCES items (id) ON DELETE CASCADE,
  number        integer NOT NULL,
  markdown      text NOT NULL,
  content_hash  text NOT NULL,
  char_count    integer NOT NULL,
  extractor     text NOT NULL,
  lang          text,
  byline        text,
  site_name     text,
  captured_at   timestamptz NOT NULL,
  captured_by   uuid NOT NULL REFERENCES users (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (item_id, number)
);

-- Retrieval units. Only the current version of an item is chunked; older versions keep their text
-- in item_versions but have no rows here. Deleting an item removes its chunks (unshare).
-- The embedding dimension is fixed by the model (multilingual-e5-small = 384); changing the model
-- to another dimension needs a migration.
CREATE TABLE chunks (
  id               uuid PRIMARY KEY,
  space_id         uuid NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  item_id          uuid NOT NULL REFERENCES items (id) ON DELETE CASCADE,
  item_version_id  uuid NOT NULL REFERENCES item_versions (id) ON DELETE CASCADE,
  ord              integer NOT NULL,
  heading_path     text NOT NULL DEFAULT '',
  text             text NOT NULL,
  char_count       integer NOT NULL,
  embedding        vector(384) NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (item_version_id, ord)
);
CREATE INDEX chunks_space_idx ON chunks (space_id);
CREATE INDEX chunks_item_idx ON chunks (item_id);
CREATE INDEX chunks_embedding_idx ON chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX chunks_text_trgm_idx ON chunks USING gin (text gin_trgm_ops);

CREATE TABLE threads (
  id               uuid PRIMARY KEY,
  space_id         uuid NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  visibility       text NOT NULL CHECK (visibility IN ('private', 'space')),
  owner_id         uuid NOT NULL REFERENCES users (id),
  title            text NOT NULL DEFAULT '',
  created_at       timestamptz NOT NULL DEFAULT now(),
  last_message_at  timestamptz
);
CREATE INDEX threads_space_idx ON threads (space_id, visibility);

CREATE TABLE messages (
  id              uuid PRIMARY KEY,
  thread_id       uuid NOT NULL REFERENCES threads (id) ON DELETE CASCADE,
  role            text NOT NULL CHECK (role IN ('user', 'assistant')),
  -- The member who wrote it, or who asked for it when role = 'assistant'.
  author_id       uuid NOT NULL REFERENCES users (id),
  model_provider  text,
  model_id        text,
  content         text NOT NULL DEFAULT '',
  -- Citation[] from @tiger/shared. `quote` is emptied when the cited item is unshared.
  citations       jsonb NOT NULL DEFAULT '[]',
  status          text NOT NULL DEFAULT 'complete' CHECK (status IN ('streaming', 'complete', 'error')),
  error_code      text,
  usage           jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX messages_thread_idx ON messages (thread_id, created_at);

-- Page content a member attached to one message of their own private thread. Never shared with the
-- Space, never indexed for retrieval, deleted with the thread, and dropped when the thread is
-- promoted to the Space.
CREATE TABLE message_attachments (
  id           uuid PRIMARY KEY,
  message_id   uuid NOT NULL REFERENCES messages (id) ON DELETE CASCADE,
  url          text NOT NULL,
  title        text NOT NULL,
  source_type  text NOT NULL,
  markdown     text NOT NULL,
  char_count   integer NOT NULL
);
CREATE INDEX message_attachments_message_idx ON message_attachments (message_id);

-- Append-only. target_* are copied in so the line still renders after the target is deleted.
CREATE TABLE audit_events (
  id            uuid PRIMARY KEY,
  space_id      uuid NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  actor_id      uuid NOT NULL REFERENCES users (id),
  action        text NOT NULL,
  target_type   text NOT NULL,
  target_id     text NOT NULL,
  target_title  text,
  target_url    text,
  at            timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_events_space_idx ON audit_events (space_id, at DESC);

CREATE TABLE llm_usage (
  id                   uuid PRIMARY KEY,
  space_id             uuid NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  user_id              uuid NOT NULL REFERENCES users (id),
  message_id           uuid,
  provider             text NOT NULL,
  model                text NOT NULL,
  input_tokens         bigint NOT NULL DEFAULT 0,
  output_tokens        bigint NOT NULL DEFAULT 0,
  cached_input_tokens  bigint NOT NULL DEFAULT 0,
  cache_write_tokens   bigint NOT NULL DEFAULT 0,
  cost_usd             numeric(12, 6),
  at                   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX llm_usage_space_idx ON llm_usage (space_id, at);
